class Lesson {
  String id;
  String title;
  List<String> pages;
  String coverNote;
  String watermark;
  String footerNote;
  String videoUrl;
  Lesson({required this.id, required this.title, List<String>? pages, this.coverNote = '', this.watermark = '', this.footerNote = '', this.videoUrl = ''}) : pages = pages ?? [''];
  Map<String, dynamic> toJson() => {'id': id, 'title': title, 'pages': pages, 'coverNote': coverNote, 'watermark': watermark, 'footerNote': footerNote, 'videoUrl': videoUrl};
  factory Lesson.fromJson(Map<String, dynamic> j) => Lesson(id: j['id'] ?? const Uuid().v4(), title: j['title'] ?? 'درس بلا عنوان', pages: List<String>.from(j['pages'] ?? ['']), coverNote: j['coverNote'] ?? '', watermark: j['watermark'] ?? '', footerNote: j['footerNote'] ?? '', videoUrl: j['videoUrl'] ?? '');
}

