class LinesPainter extends CustomPainter { final double opacity; LinesPainter(this.opacity); @override void paint(Canvas canvas, Size size) { final p = Paint()..color = Colors.blueGrey.withOpacity(opacity)..strokeWidth = .7; for (double y = 34; y < size.height; y += 34) { canvas.drawLine(Offset(0,y), Offset(size.width,y), p); } } @override bool shouldRepaint(covariant LinesPainter old) => old.opacity != opacity; }

